definition.script:
import groovy.json.JsonSlurper;
def psa_ref = ''
def psm_ref = ''


node {
    stage('Retrieve Build Spec') {
        script {
            if (!(params.release_control_commit ==~ /[0-9a-f]{40}/)) {
                error('PIC-SURE Database Migrations requires an exact release_control_commit; use Check For Updates.')
            }
            def result = build job: 'Retrieve Pinned Build Spec', parameters: [
                [$class: 'StringParameterValue', name: 'release_control_commit', value: params.release_control_commit]
            ]
            retrieveBuildSpecId = result.number
        }
        script {
            copyArtifacts filter: '*', projectName: 'Retrieve Pinned Build Spec', selector: specific(""+retrieveBuildSpecId)
            sh 'cat build-spec.json'
            sh 'cat pipeline_git_commit.txt'
            sh 'pwd'
            sh 'ls'
            sh '/scripts/validate-build-spec.sh build-spec.json'
            def path = pwd()
            def filePath = path + '/build-spec.json'
            echo filePath
            def buildSpec = new JsonSlurper().parse(new File(filePath))

            for(def build : buildSpec.application){
                if(build.project_job_git_key.equalsIgnoreCase("PSA")) {
                    psa_ref = build.git_hash
                    echo 'psa_ref ' + psa_ref
                }
                if(build.project_job_git_key.equalsIgnoreCase("PSM")) {
                    psm_ref = build.git_hash
                    echo 'psm_ref ' + psm_ref
                }
            }
            if(psa_ref.isEmpty() || psm_ref.isEmpty()) {
                currentBuild.result = 'ABORTED'
                echo 'psa_ref = ' + psa_ref
                echo 'psm_ref = ' + psm_ref
                error('Build Spec Not configured correctly!')
            }
        }
    }
    stage('Checkout Monorepo') {
        checkout([$class: 'GitSCM', branches: [[name: psa_ref ]],
                  extensions: [[$class: 'PruneStaleBranch']],
                  userRemoteConfigs: [[url: 'https://github.com/hms-dbmi/pic-sure']]])
    }
    stage('Auth Schema Migration') {
        def image = docker.image('dbmi/pic-sure-db-migrations:pic-sure-db-migration_v1.0')
        image.pull()
        docker.image('dbmi/pic-sure-db-migrations:pic-sure-db-migration_v1.0').inside('--network=picsure -v $DOCKER_CONFIG_DIR/flyway/auth:/opt/flyway-migrations/auth "--entrypoint=" ') {
            sh "rm -rf /opt/flyway-migrations/auth/sql"
            sh "cp -R ./services/pic-sure-auth-microapp/pic-sure-auth-db/db/sql /opt/flyway-migrations/auth/sql"
            sh "/opt/flyway/flyway -X -configFiles=/opt/flyway-migrations/auth/flyway-auth.conf migrate"
            sleep(time:1,unit:"SECONDS")
        }
    }
    stage('Picsure Schema Migration') {
        docker.image('dbmi/pic-sure-db-migrations:pic-sure-db-migration_v1.0').inside('--network=picsure -v $DOCKER_CONFIG_DIR/flyway/picsure:/opt/flyway-migrations/picsure "--entrypoint=" ') {
            sh "rm -rf /opt/flyway-migrations/picsure/sql"
            sh "cp -R ./services/pic-sure-operations-service/db/sql /opt/flyway-migrations/picsure/sql"
            sh "/opt/flyway/flyway -X -configFiles=/opt/flyway-migrations/picsure/flyway-picsure.conf migrate"
            sleep(time:1,unit:"SECONDS")
        }
    }
    stage('Project Specific Migrations') {
        checkout([$class: 'GitSCM', branches: [[name: psm_ref ]],
                  extensions: [[$class: 'PruneStaleBranch']],
                  userRemoteConfigs: [[url: MIGRATION_REPO]]])
        sh """
            sed -i "s/__APPLICATION_UUID__/`cat /usr/local/docker-config/APP_ID_HEX`/g" ./${MIGRATION_NAME}/auth/*.sql
            sed -i "s/__RESOURCE_UUID__/`cat /usr/local/docker-config/RESOURCE_ID_HEX`/g" ./${MIGRATION_NAME}/picsure/*.sql
        """
        docker.image('dbmi/pic-sure-db-migrations:pic-sure-db-migration_v1.0').inside('--network=picsure -v $DOCKER_CONFIG_DIR/flyway/picsure:/opt/flyway-migrations/picsure "--entrypoint=" ') {
            sh "rm -rf /opt/flyway-migrations/picsure/sql"
            sh "cp -R ./${MIGRATION_NAME}/picsure /opt/flyway-migrations/picsure/sql"
            sh "/opt/flyway/flyway -X -baselineOnMigrate=true -configFiles=/opt/flyway-migrations/picsure/flyway-picsure.conf -table=flyway_custom_schema_history migrate"
            sleep(time:1,unit:"SECONDS")
        }
        docker.image('dbmi/pic-sure-db-migrations:pic-sure-db-migration_v1.0').inside('--network=picsure -v $DOCKER_CONFIG_DIR/flyway/auth:/opt/flyway-migrations/auth "--entrypoint=" ') {
            sh "rm -rf /opt/flyway-migrations/auth/sql"
            sh "cp -R ./${MIGRATION_NAME}/auth /opt/flyway-migrations/auth/sql"
            sh "/opt/flyway/flyway -X -baselineOnMigrate=true -configFiles=/opt/flyway-migrations/auth/flyway-auth.conf -table=flyway_custom_schema_history migrate"
            sleep(time:1,unit:"SECONDS")
        }
    }
    stage('Dictionary Migrations') {
        script {
            echo "Migrating Dictionary Database"
            def result = build job: 'Migrate Dictionary Database', parameters: [
                    [$class: 'StringParameterValue', name: 'git_hash', value: psa_ref]
            ]
        }
    }
    stage('Record Migration Input') {
        writeFile file: 'migration-release-control-commit.txt', text: params.release_control_commit + '\n'
        archiveArtifacts artifacts: 'migration-release-control-commit.txt', fingerprint: true
    }
    stage('Clean Workspace'){
        cleanWs()
    }

}
